-- ==============================================
-- ARTICLE: El Juego del Vampiro (el-juego-del-vampiro)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'el-juego-del-vampiro';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'El Juego del Vampiro',
    'el-juego-del-vampiro',
    $html$<h2>📜 Descripción del Juego</h2><p><strong>El Juego del Vampiro</strong> es un clásico e intrigante juego de acecho e intriga scout para campamentos. Cada participante recibe en secreto una tarjeta con el nombre de su "víctima". El objetivo es tocar discretamente el hombro o cuello de la víctima pronunciando <em>"vampiro"</em> en total ausencia de testigos visuales.</p><hr><h3>🎲 ¿Cómo se juega?</h3><ol><li><strong>El Mural del Cementerio:</strong> En la sede o campamento se instala un mural representativo ("el cementerio") donde figuran todas las lápidas de los participantes.</li><li><strong>Reparto Secreto de Tarjetas:</strong> Cada participante saca una tarjeta con el nombre del scout al que debe "cazar". Nadie debe revelar su objetivo a los demás.</li><li><strong>La Caza en Solitario:</strong> A lo largo de la jornada de campamento, los participantes realizan sus actividades normales mientras observan a su víctima. Para efectuar la eliminación ("morder"), se debe tocar suavemente al objetivo cuando <strong>ningún otro scout esté mirando</strong>.</li><li><strong>Registro de Eliminados:</strong> El scout "mordido" entrega su tarjeta al vampiro que lo atrapó y marca su tumba en el mural del cementerio. El cazador asume entonces a la víctima de la persona eliminada.</li><li><strong>Fin del Juego:</strong> El juego termina cuando sólo queda un vampiro victorioso o al finalizar el campamento, recompensando al scout con más eliminaciones limpias.</li></ol>$html$,
    'Un clásico juego de acecho e intriga scout para campamentos donde se eliminan objetivos en secreto sin dejar testigos.',
    '/uploads/actividad_elJuegoDelVampiro.webp',
    'publicado',
    ARRAY['juego-nocturno', 'acecho', 'panolines', 'campamento', 'observacion'],
    $json${"areas": ["creatividad", "sociabilidad", "carácter"], "lugares": ["Exterior", "campo abierto"], "cantidad": "04 participantes", "duracion": "todo el día", "unidades": ["tropa", "compañía", "avanzada", "clan"], "descargas": [], "objetivos": ["Sigilo y acecho", "Desarrollo de la observación", "Introspección", "Crear un clima de pertenencia"], "materiales": ["Tarjetas de Papel", "Lápices", "Sin Materiales"], "variaciones": "<b>Vampiros Nocturnos:</b> El juego se realiza exclusivamente durante el fogón o la velada nocturna en un perímetro delimitado por linternas.<br/><br/>\n\n<b>Variante con Pañolín:</b> En lugar de tocar el hombro, el cazador debe retirar sigilosamente el <b>pañolín</b> del cinturón de su víctima sin que nadie en el área se dé cuenta.<br/><br/>\n\n<b>Protección de Testigos:</b> Si la víctima está acompañada por al menos dos compañeros, es inmune al ataque hasta que quede a solas o aislada.<br/><br/>", "recomendaciones": "<b>Respeto a las Tareas de Campamento:</b> Establecer que no se pueden realizar eliminaciones durante momentos solemnes, ceremonias de <b>pañolín</b> ni durante la preparación de alimentos.<br/><br/>\n\n<b>Absoluta Honestidad:</b> Remarcar el Código de Honor Scout; si hubo un testigo mirando, la eliminación queda automáticamente anulada.<br/><br/>\n\n<b>Rol de Dirigentes:</b> Supervisar con discreción la entrega de tarjetas y animar el mural del cementerio con misterio y humor pedagógico.", "justificacion_areas": "El Juego del Vampiro estimula la creatividad al requerir observación sutil, astucia y planificación de emboscadas sin llamar la atención. Desarrolla la sociabilidad al afianzar la deportividad, el respeto por las reglas de honor y la convivencia fraterna, y ejercita el carácter al cultivar la paciencia, la templanza y el sentido del humor.", "objetivos_educativos": [{"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Observando con atención el entorno para detectar movimientos sospechosos de otros vampiros."}, {"id": "beb4b3e4-fe1c-4f06-af34-2c7f88202eb7", "area": "Creatividad", "texto": "Me gusta cantar y conozco muchas canciones.", "unidad": "Compañía", "como_se_cumple": "Desarrollando la astucia y la paciencia durante las rutinas diarias de la unidad."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Fomentando un ambiente de camaradería y deportividad ante los aciertos ajenos."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Disfrutando el misterio y las risas al revelar los nombres al final de la jornada."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Demostrando autocontrol y templanza durante los momentos de acecho."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Velando por la inclusión activa y el juego limpio de todas las participantes."}, {"id": "981fa19b-7f60-4e0e-b2fa-16123df5e37e", "area": "Creatividad", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "unidad": "Tropa", "como_se_cumple": "Creando oportunidades discretas para tocar al compañero asignado sin ser descubierto."}, {"id": "f9cea3e0-24f4-43ab-9efb-1a4541a29943", "area": "Creatividad", "texto": "Ayudo a preparar materiales para las representaciones artísticas.", "unidad": "Tropa", "como_se_cumple": "Planificando estrategias de distracción e imitación de conducta en el campamento."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Tomando con humor y deportividad ser eliminado en secreto por otro cazador."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Afrontando el suspenso del juego con serenidad, alegría y entusiasmo."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Respetando las reglas de caballerosidad y honestidad al cantar la eliminación."}, {"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Cuidando que las acciones del juego no interfieran con las tareas de servicio de la patrulla."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "unidad": "Avanzada", "como_se_cumple": "Diseñando emboscadas creativas aprovechando la topografía y dinámicas de grupo."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "area": "Carácter", "texto": "Soy capaz de reírme de mis propios absurdos.", "unidad": "Avanzada", "como_se_cumple": "Viviendo la incertidumbre con madurez emocional y sentido del humor."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "area": "Sociabilidad", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "unidad": "Avanzada", "como_se_cumple": "Manteniendo la fraternidad y el buen ambiente en la comunidad de avanzada."}, {"id": "d716bdfb-2fea-4b96-9a46-b86d66692d45", "area": "Carácter", "texto": "Enfrento la vida con alegría y sentido del humor.", "unidad": "Clan", "como_se_cumple": "Reflexionando sobre la agudeza visual y el autocontrol con actitud abierta."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "texto": "Expreso lo que pienso y siento a través de distintos medios, creando en los ambientes en que actúo espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "unidad": "Clan", "como_se_cumple": "Implementando técnicas avanzadas de camuflaje social e introspección táctica."}, {"id": "b5a81328-5c07-41bd-a1ea-1ed401762841", "area": "Sociabilidad", "texto": "Vivo mi libertad de un modo solidario, ejerciendo mis derechos, cumpliendo mis obligaciones y defendiendo igual derecho para los demás.", "unidad": "Clan", "como_se_cumple": "Promoviendo el respeto mudo y la responsabilidad en el servicio del campamento."}]}$json$::jsonb
  );

  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 1) ON CONFLICT DO NOTHING;
