  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '25b24d3a-9d47-44af-b460-680508e644f3', 'Demostrando autocontrol y templanza durante los momentos de acecho.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4b2e406f-2d78-4039-9ce2-4ccb743eb553', 'Viviendo la incertidumbre con madurez emocional y sentido del humor.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4d66ed86-48ec-4801-bd0a-e5c8d023c8cd', 'Tomando con humor y deportividad ser eliminado en secreto por otro cazador.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '5abfbe81-75e4-4444-b52d-38e59e8b6ec7', 'Manteniendo la fraternidad y el buen ambiente en la comunidad de avanzada.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '91e60eba-e267-4d1a-b27b-ef61a7b03b31', 'Implementando técnicas avanzadas de camuflaje social e introspección táctica.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '944660c8-0093-4181-ba2c-5f95cc74ba47', 'Velando por la inclusión activa y el juego limpio de todas las participantes.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '981fa19b-7f60-4e0e-b2fa-16123df5e37e', 'Creando oportunidades discretas para tocar al compañero asignado sin ser descubierto.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '9a38e454-f93a-40a5-9f68-e500ba7e0655', 'Afrontando el suspenso del juego con serenidad, alegría y entusiasmo.') ON CONFLICT DO NOTHING;
